def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "play_acceptance": And([
            self.verbal_invitation_heard(),
            self.robot_has(self.acceptance_message),
            self.neighbor_is_minor,
            Not(self.message_played(self.acceptance_message))
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
